using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
using System.Windows.Forms;
namespace Aster {
static class AsterBackup {
 public const long MaxTotal=20*1048576;public const int MaxFile=1048576,MaxEntries=600;
 public static bool Allowed(string name){if(name=="Workspace.json"||name=="PersonalWorkspace.json"||name=="NetworkHistory.json")return true;return name.StartsWith("Cases/",StringComparison.Ordinal)&&name.EndsWith(".json",StringComparison.OrdinalIgnoreCase)&&name.Length>11&&name.Substring(6).All(c=>char.IsLetterOrDigit(c)||c=='-'||c=='_'||c=='.')&&!name.Contains("..");}
 static void SafeExisting(string path){if((File.Exists(path)||Directory.Exists(path))&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked files or folders are not supported: "+Path.GetFileName(path));}
 static string Target(string root,string name){if(!Allowed(name))throw new Exception("Unsupported archive entry: "+name);root=Path.GetFullPath(root);SafeExisting(root);if(name.StartsWith("Cases/"))SafeExisting(Path.Combine(root,"Cases"));string path=Path.GetFullPath(Path.Combine(root,name.Replace('/',Path.DirectorySeparatorChar)));if(!path.StartsWith(root.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Invalid target path.");SafeExisting(path);return path;}
 static void Validate(string name,byte[] bytes){if(!Allowed(name)||bytes.Length>MaxFile)throw new Exception("Unsupported or oversized entry: "+name);string text=new UTF8Encoding(false,true).GetString(bytes).TrimStart('\uFEFF');var json=new JavaScriptSerializer{MaxJsonLength=MaxFile};if(name=="PersonalWorkspace.json")PersonalStore.Validate(json.Deserialize<PersonalData>(text));else if(name=="Workspace.json"){var p=json.Deserialize<WorkspaceOptions>(text);if(p==null||!new[]{1000,2000,3000,5000}.Contains(p.Interval)||p.Pins==null||p.Pins.Count>100||p.Pins.Any(n=>string.IsNullOrWhiteSpace(n)||n.Length>100))throw new Exception("Invalid settings file.");if(p.ThemeId=="custom")CustomTheme.Create(new ThemeRecipe{Background=p.CustomBase,Accent=p.CustomAccent});}else if(name=="NetworkHistory.json"){var rows=json.Deserialize<List<NetworkResult>>(text);if(rows==null||rows.Count>50||rows.Any(r=>r==null))throw new Exception("Invalid network history.");}else{var c=json.Deserialize<SupportCase>(text);if(c==null||c.Version!=1||string.IsNullOrWhiteSpace(c.Title))throw new Exception("Invalid saved case: "+name);}}
 public static Dictionary<string,byte[]> Read(string path){if(new FileInfo(path).Length>MaxTotal+1048576)throw new Exception("Archive exceeds 21 MiB.");var result=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);long total=0;using(var zip=ZipFile.OpenRead(path)){if(zip.Entries.Count==0||zip.Entries.Count>MaxEntries)throw new Exception("Archive must contain 1–600 supported files.");foreach(var entry in zip.Entries){if(!Allowed(entry.FullName)||result.ContainsKey(entry.FullName)||entry.Length>MaxFile||(total+=entry.Length)>MaxTotal)throw new Exception("Unsafe, duplicate or oversized archive entry: "+entry.FullName);using(var input=entry.Open())using(var output=new MemoryStream()){byte[] buffer=new byte[8192];int count;while((count=input.Read(buffer,0,buffer.Length))>0){if(output.Length+count>MaxFile)throw new Exception("Expanded entry too large.");output.Write(buffer,0,count);}var bytes=output.ToArray();if(bytes.LongLength!=entry.Length)throw new Exception("Incomplete archive entry.");Validate(entry.FullName,bytes);result.Add(entry.FullName,bytes);}}}return result;}
 static Dictionary<string,byte[]> Collect(string root){var entries=new Dictionary<string,byte[]>();SafeExisting(root);var names=new List<string>{"Workspace.json","PersonalWorkspace.json","NetworkHistory.json"};string cases=Path.Combine(root,"Cases");SafeExisting(cases);if(Directory.Exists(cases))names.AddRange(Directory.GetFiles(cases,"*.json",SearchOption.TopDirectoryOnly).Select(p=>"Cases/"+Path.GetFileName(p)));long total=0;foreach(var name in names){string path=Target(root,name);if(!File.Exists(path))continue;var info=new FileInfo(path);if(info.Length>MaxFile||(total+=info.Length)>MaxTotal||entries.Count>=MaxEntries)throw new Exception("Backup limit exceeded: 600 files, 1 MiB each, 20 MiB total.");var bytes=File.ReadAllBytes(path);Validate(name,bytes);entries.Add(name,bytes);}return entries;}
 static void Write(string path,Dictionary<string,byte[]> entries){string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var zip=ZipFile.Open(temp,ZipArchiveMode.Create)){foreach(var item in entries){var e=zip.CreateEntry(item.Key,CompressionLevel.Optimal);using(var stream=e.Open())stream.Write(item.Value,0,item.Value.Length);}}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static int Create(string root,string destination){var entries=Collect(root);if(entries.Count==0)throw new Exception("No saved Aster settings, notes, history or cases were found yet.");Write(destination,entries);return entries.Count;}
 static void WriteTarget(string path,byte[] bytes){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllBytes(temp,bytes);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static string Restore(string root,Dictionary<string,byte[]> entries){if(entries.Count==0||entries.Count>MaxEntries||entries.Sum(x=>(long)x.Value.Length)>MaxTotal)throw new Exception("Invalid restore size.");var before=new Dictionary<string,byte[]>();foreach(var item in entries){Validate(item.Key,item.Value);string p=Target(root,item.Key);if(File.Exists(p)){if(new FileInfo(p).Length>MaxFile)throw new Exception("Existing destination file is too large to back up.");before[item.Key]=File.ReadAllBytes(p);}}Directory.CreateDirectory(root);string backupFolder=Path.Combine(root,"Backups");SafeExisting(backupFolder);Directory.CreateDirectory(backupFolder);string recovery=Path.Combine(backupFolder,"before-restore-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")+".zip");Write(recovery,before);var written=new List<string>();try{foreach(var item in entries){WriteTarget(Target(root,item.Key),item.Value);written.Add(item.Key);}}catch(Exception ex){var errors=new List<string>();foreach(string name in written.AsEnumerable().Reverse()){try{string path=Target(root,name);if(before.ContainsKey(name))WriteTarget(path,before[name]);else if(File.Exists(path))File.Delete(path);}catch(Exception rollback){errors.Add(rollback.Message);}}throw new Exception("Restore failed: "+ex.Message+"\r\n"+(errors.Count==0?"Written files rolled back.":"Some rollback steps failed: "+string.Join("; ",errors))+"\r\nPre-restore backup: "+recovery);}return recovery;}
}
partial class MainWindow {
 void BuildBackupCenter(){sub.Text="Local backups · review before restoring · no Windows system files";string rootPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse");Dictionary<string,byte[]> selected=null;var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(12)};root.RowStyles.Add(new RowStyle(SizeType.Absolute,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(root);root.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Back up saved Aster preferences, notebook/checklist, network history and saved cases. Backups are ordinary ZIP files, not encrypted. They may contain personal notes and diagnostic data.\r\nRestore merges the archive: matching files are replaced; unrelated files stay. Current matching files are backed up automatically before replacement. Close other Aster copies first. Wallpaper files and Windows repairs are not included."},0,0);var buttonsRow=new FlowLayoutPanel{Dock=DockStyle.Fill};root.Controls.Add(buttonsRow,0,1);var review=ReadableText();review.Text="Create an archive, or choose one to validate and review its file list.";root.Controls.Add(review,0,2);var create=Button("Create backup ZIP");create.Click+=(s,e)=>{try{if(personalDirty){if(MessageBox.Show(this,"Save current notebook/checklist edits before creating the backup?","Save edits",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;if(!SavePersonal())return;}using(var d=new SaveFileDialog{Filter="Aster backup|*.zip",FileName="Aster-backup-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".zip"})if(d.ShowDialog(this)==DialogResult.OK){int count=AsterBackup.Create(rootPath,d.FileName);review.Text="Backed up "+count+" files to:\r\n"+d.FileName;}}catch(Exception ex){review.Text=ex.Message;}};buttonsRow.Controls.Add(create);var choose=Button("Choose backup to review");var restore=Button("Restore reviewed files");restore.Enabled=false;choose.Click+=(s,e)=>{using(var d=new OpenFileDialog{Filter="Aster backup|*.zip"})if(d.ShowDialog(this)==DialogResult.OK){selected=null;restore.Enabled=false;try{selected=AsterBackup.Read(d.FileName);review.Text="VALIDATED ARCHIVE · "+selected.Count+" files\r\n\r\n"+string.Join("\r\n",selected.Select(pair=>(File.Exists(Path.Combine(rootPath,pair.Key.Replace('/',Path.DirectorySeparatorChar)))?"REPLACE  ":"ADD      ")+pair.Key+" · "+pair.Value.Length+" bytes"))+"\r\n\r\nOnly the listed files will be written. Saved settings apply immediately. Notes/checklist are reloaded only if they are included in this archive.";restore.Enabled=true;}catch(Exception ex){review.Text="Archive rejected: "+ex.Message;}}};buttonsRow.Controls.Add(choose);restore.Click+=(s,e)=>{if(selected==null)return;if(MessageBox.Show(this,"Restore the reviewed "+selected.Count+" files? Matching files will be replaced and backed up first."+(personalDirty&&selected.ContainsKey("PersonalWorkspace.json")?"\r\nYou have unsaved notebook/checklist changes. Cancel and save them first to include them in the pre-restore backup.":""),"Confirm reviewed restore",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.OK)return;try{string backup=AsterBackup.Restore(rootPath,selected);ApplyRestoredWorkspace(selected.Keys);review.Text="Restore completed. Prior matching files are in:\r\n"+backup+"\r\n\r\nUnrelated files were left in place.";selected=null;restore.Enabled=false;}catch(Exception ex){review.Text=ex.Message;}};buttonsRow.Controls.Add(restore);}
 void ApplyRestoredWorkspace(IEnumerable<string> files){var restored=new HashSet<string>(files,StringComparer.OrdinalIgnoreCase);if(restored.Contains("Workspace.json")){preferences=WorkspaceOptions.Read();timer.Interval=preferences.Interval;TopMost=preferences.AlwaysOnTop;}if(restored.Contains("PersonalWorkspace.json")){try{personal=PersonalStore.Read();personalLoadError=null;}catch(Exception ex){personalLoadError=ex.Message;}personalDirty=false;}RebuildNavigation();RefreshDailyPicture();ApplyAppTheme();}
}
}

